import React, { useEffect, useState } from 'react';
// import axios from 'axios';
import { useSelector } from 'react-redux';
import api from "../../../../api/axios";


const EmployeeDashboard = () => {
  const token = useSelector((state) => state.auth.token);
  const user = useSelector((state) => state.auth.user); // <--- add this line
  const [tickets, setTickets] = useState([]);

  useEffect(() => {
    const fetchTickets = async () => {
      const response = await api.get('/api/tickets/', {
        headers: { Authorization: `Bearer ${token}` },
      });
      // filter tickets created by logged-in user
      setTickets(response.data.filter(ticket => ticket.creator.id === user.id));
    };
    if (user) fetchTickets(); // make sure user is loaded
  }, [token, user]);

  return (
    <div>
      <h2>My Tickets</h2>
      {tickets.map(ticket => (
        <div key={ticket.id} style={{ border: '1px solid gray', margin: '10px', padding: '10px' }}>
          <h4>{ticket.title}</h4>
          <p>Priority: {ticket.priority}</p>
          <p>Status: {ticket.status}</p>
        </div>
      ))}
    </div>
  );
};

export default EmployeeDashboard;
